def crear_excepciones_existentes(apps, schema_editor):
    """Las conciliaciones en pesos guardadas antes del CU-04 tienen sus ventas por revisar y cuotas en
    el resultado: se convierten en excepciones pendientes (de la más antigua a la más nueva, para que
    una venta repetida quede vigente solo en la última). Las en dólares antiguas no guardaban el
    detalle de cada venta: sus excepciones aparecen al conciliar de nuevo."""
    from apps.conciliacion import excepciones

    Conciliacion = apps.get_model("conciliacion", "Conciliacion")
    Excepcion = apps.get_model("conciliacion", "Excepcion")
    for c in Conciliacion.objects.filter(moneda="CLP").order_by("creada", "pk").iterator():
        if Excepcion.objects.filter(conciliacion=c).exists():
            continue
        r = c.resultado or {}
        casos = excepciones.desde_clp(r.get("observaciones"), r.get("cuotas"))
        Excepcion.objects.bulk_create([Excepcion(**excepciones.campos_excepcion(c, i, k)) for i, k in enumerate(casos)])
        excepciones.heredar_gestion(Excepcion, c)


Migration.operations.append(migrations.RunPython(crear_excepciones_existentes, migrations.RunPython.noop))
